// GRE Vocabulary Database — Part 5
const VOCAB_DATA_5 = [
  {word:"ebb",partOfSpeech:"verb/noun",definition:"to gradually decrease; the movement of the tide out to sea",difficulty:1,mnemonic:"'EBB' — a tiny word for a shrinking thing. When the tide EBBS, the water recedes. Enthusiasm can ebb too.",etymology:"Old English 'ebba' = low tide (related to 'of' = away)",exampleSentence:"Public enthusiasm for the project began to ebb as costs continued to rise.",synonyms:["recede","diminish","wane","subside","decline"],antonyms:["flow","increase","surge","grow","rise"],confusedWith:["web"],tags:["change","decrease"]},
  {word:"edify",partOfSpeech:"verb",definition:"to instruct or improve someone morally or intellectually",difficulty:2,mnemonic:"'EDI-FY' — like an EDItor who FIXes your writing and makes you better. Education that builds you up, like an edifice!",etymology:"Latin 'aedificare' = to build (aedes 'dwelling' + facere 'to make') — originally literal building, then figurative 'building character'",exampleSentence:"The documentary was both entertaining and edifying, teaching viewers about deep-sea ecosystems.",synonyms:["enlighten","educate","instruct","improve","uplift"],antonyms:["corrupt","mislead","debase"],confusedWith:["editable"],tags:["education","positive"]},
  {word:"effervescent",partOfSpeech:"adjective",definition:"giving off bubbles; vivacious and enthusiastic",difficulty:2,mnemonic:"'EFFER-VES-CENT' — like an EFFERVESCENT tablet fizzing in water. A bubbly, fizzy personality!",etymology:"Latin 'effervescere' = to boil up (ex- 'out' + fervescere 'to begin to boil')",exampleSentence:"Her effervescent personality made her popular at social gatherings.",synonyms:["bubbly","vivacious","lively","sparkling","exuberant"],antonyms:["flat","dull","lifeless","subdued","listless"],confusedWith:["ebullient"],tags:["personality","positive"]},
  {word:"egregious",partOfSpeech:"adjective",definition:"outstandingly bad; shocking; remarkably good (archaic)",difficulty:2,mnemonic:"'E-GREG-IOUS' — GREG committed an error SO BAD it stood out from the group (gregarious). Shockingly terrible!",etymology:"Latin 'egregius' = outstanding (e- 'out of' + grex 'flock') — ironically shifted from 'outstandingly good' to 'outstandingly bad'",exampleSentence:"The report documented egregious violations of safety standards at the factory.",synonyms:["flagrant","outrageous","appalling","glaring","atrocious"],antonyms:["minor","slight","mild","trivial"],confusedWith:["gregarious"],tags:["severity","negative"]},
  {word:"elicit",partOfSpeech:"verb",definition:"to evoke or draw out a response, answer, or fact from someone",difficulty:1,mnemonic:"'E-LICIT' — to draw out something that's ILLICIT (hidden). Pulling information out of someone!",etymology:"Latin 'elicere' = to draw out (e- 'out' + lacere 'to entice, deceive')",exampleSentence:"The comedian's jokes never failed to elicit laughter from the audience.",synonyms:["evoke","extract","draw out","provoke","prompt"],antonyms:["suppress","repress","quell","stifle"],confusedWith:["illicit"],tags:["response","draw out"]},
  {word:"embellish",partOfSpeech:"verb",definition:"to make something more attractive by decoration; to make a story more interesting by adding details",difficulty:1,mnemonic:"'EM-BELL-ISH' — adding BELLS to make something more decorative and pretty. Embellishing = adding ornaments (or exaggerations)!",etymology:"Old French 'embellir' = to make beautiful (en- + bel 'beautiful')",exampleSentence:"He had a tendency to embellish his stories, adding dramatic details that never actually happened.",synonyms:["adorn","decorate","ornament","exaggerate","elaborate"],antonyms:["simplify","strip","understate"],confusedWith:[],tags:["decoration","exaggeration"]},
  {word:"eminent",partOfSpeech:"adjective",definition:"famous and respected within a particular sphere or profession; notable",difficulty:1,mnemonic:"'EM-IN-ENT' — someone who is IN the spotlight, ENTering the scene with fame. Standing above the rest!",etymology:"Latin 'eminens' = standing out (from 'eminere' = to stand out; e- 'out' + minere 'to project')",exampleSentence:"The conference attracted eminent scholars from universities around the world.",synonyms:["distinguished","renowned","prominent","illustrious","notable"],antonyms:["unknown","obscure","insignificant","ordinary"],confusedWith:["imminent","eminent domain"],tags:["status","respect"]},
  {word:"enmity",partOfSpeech:"noun",definition:"the state or feeling of being actively opposed or hostile to someone or something",difficulty:2,mnemonic:"'EN-MY-TY' — your ENEMY + TY (hostility). The feeling between ENEMies. Deep-rooted hatred.",etymology:"Old French 'enemite' (from Latin 'inimicitia' = hostility, from 'inimicus' = enemy)",exampleSentence:"The enmity between the two families had persisted for generations.",synonyms:["hostility","animosity","antagonism","hatred","antipathy"],antonyms:["friendship","amity","goodwill","harmony"],confusedWith:["amity","enemy"],tags:["hostility","emotion"]},
  {word:"enumerate",partOfSpeech:"verb",definition:"to mention a number of things one by one; to count",difficulty:1,mnemonic:"'E-NUMBER-ATE' — to put NUMBERS on things, listing them one by one. 1, 2, 3... enumerating!",etymology:"Latin 'enumerare' = to count out (e- 'out' + numerare 'to count')",exampleSentence:"The report enumerated over twenty specific policy recommendations.",synonyms:["list","itemize","catalog","specify","count"],antonyms:["summarize","generalize"],confusedWith:[],tags:["listing","counting"]},
  {word:"epitome",partOfSpeech:"noun",definition:"a person or thing that is a perfect example of a particular quality or type",difficulty:1,mnemonic:"'EPI-TOME' — the EPIC TOME (book) that perfectly represents a genre. THE example of something. She IS elegance.",etymology:"Greek 'epitome' = abridgment, summary (from 'epitemnein' = to cut short; epi- 'into' + temnein 'to cut')",exampleSentence:"She was the epitome of grace under pressure during the crisis.",synonyms:["embodiment","personification","exemplar","quintessence","archetype"],antonyms:["antithesis","opposite"],confusedWith:["epilogue"],tags:["example","ideal"]},
  {word:"equitable",partOfSpeech:"adjective",definition:"fair and impartial; just and reasonable",difficulty:1,mnemonic:"'EQUI-TABLE' — setting an EQUAL TABLE where everyone gets a fair share. EQUI = equal = fair for all.",etymology:"French 'équitable' (from Latin 'aequitas' = fairness, from 'aequus' = even, fair)",exampleSentence:"The mediator worked to reach an equitable settlement that satisfied both parties.",synonyms:["fair","just","impartial","unbiased","reasonable"],antonyms:["unfair","unjust","biased","inequitable"],confusedWith:["equal","equivalent"],tags:["fairness","justice"]},
  {word:"erratic",partOfSpeech:"adjective",definition:"not even or regular in pattern or movement; unpredictable",difficulty:1,mnemonic:"'ERR-ATIC' — full of ERRORS and randomness. Erratic behavior = all over the place, like a pinball bouncing randomly.",etymology:"Latin 'erraticus' = wandering (from 'errare' = to wander, err)",exampleSentence:"Her erratic driving alarmed the other motorists on the highway.",synonyms:["unpredictable","inconsistent","irregular","volatile","capricious"],antonyms:["steady","consistent","predictable","regular"],confusedWith:["erroneous"],tags:["behavior","unpredictable"]},
  {word:"erroneous",partOfSpeech:"adjective",definition:"wrong; incorrect; based on false reasoning",difficulty:1,mnemonic:"'ERROR-NEOUS' — full of ERRORS. Simple! An erroneous conclusion = a wrong conclusion.",etymology:"Latin 'erroneus' = wandering (from 'errare' = to wander, err — wandering from the truth)",exampleSentence:"The report was based on erroneous data that significantly skewed the results.",synonyms:["incorrect","wrong","mistaken","false","inaccurate"],antonyms:["correct","accurate","true","right"],confusedWith:["erratic"],tags:["accuracy","wrong"]},
  {word:"eschew",partOfSpeech:"verb",definition:"to deliberately avoid using or participating in; to abstain from",difficulty:2,mnemonic:"'E-SHOE' — imagine throwing your SHOE away because you've decided to avoid wearing shoes forever. You ESCHEW shoes!",etymology:"Old French 'eschiver' = to avoid, shun (from Germanic *skiuhan = to dread)",exampleSentence:"She eschewed social media entirely, preferring face-to-face communication.",synonyms:["avoid","shun","abstain from","forgo","steer clear of"],antonyms:["embrace","adopt","pursue","seek"],confusedWith:["chew"],tags:["avoidance","choice"]},
  {word:"eulogy",partOfSpeech:"noun",definition:"a speech or piece of writing that praises someone highly, especially one given at a funeral",difficulty:2,mnemonic:"'EU-LOGY' — EU = good (like euphoria), LOGY = words/speech. GOOD WORDS about someone, especially at their funeral.",etymology:"Greek 'eulogia' = praise (eu- 'well, good' + logos 'word, speech')",exampleSentence:"She delivered a heartfelt eulogy that captured the essence of her father's life.",synonyms:["tribute","panegyric","encomium","accolade","commemoration"],antonyms:["condemnation","criticism","denunciation"],confusedWith:["elegy","apology"],tags:["speech","death"]},
  {word:"euphemism",partOfSpeech:"noun",definition:"a mild or indirect word or expression substituted for one considered too harsh or blunt",difficulty:1,mnemonic:"'EU-PHEM-ISM' — EU = good, PHEM = speak (like 'phone'). Speaking in a GOOD/gentle way instead of harshly. 'Passed away' instead of 'died.'",etymology:"Greek 'euphemismos' (eu- 'good' + pheme 'speaking')",exampleSentence:"'Downsizing' is a corporate euphemism for laying off employees.",synonyms:["understatement","softening","politeness","indirect expression"],antonyms:["dysphemism","bluntness","directness"],confusedWith:["euphoria"],tags:["language","indirect"]},
  {word:"exalt",partOfSpeech:"verb",definition:"to hold someone or something in very high regard; to elevate in rank or power",difficulty:2,mnemonic:"'EX-ALT' — to put on the highest ALTitude. Raising someone up to the sky with praise!",etymology:"Latin 'exaltare' = to raise high (ex- 'out, upward' + altus 'high')",exampleSentence:"The community exalted her as a hero for her selfless actions during the flood.",synonyms:["praise","glorify","elevate","extol","laud"],antonyms:["humble","degrade","demote","criticize","belittle"],confusedWith:["exult"],tags:["praise","elevation"]},
  {word:"exemplary",partOfSpeech:"adjective",definition:"serving as a desirable model; representing the best of its kind; serving as a warning",difficulty:1,mnemonic:"'EXAMPLE-ARY' — worthy of being an EXAMPLE. So good it should be the model everyone follows!",etymology:"Latin 'exemplaris' = serving as a pattern (from 'exemplum' = example)",exampleSentence:"Her exemplary conduct earned her the Employee of the Year award.",synonyms:["outstanding","model","ideal","commendable","admirable"],antonyms:["deplorable","terrible","reprehensible","poor"],confusedWith:["exemplify"],tags:["quality","positive"]},
  {word:"exhort",partOfSpeech:"verb",definition:"to strongly encourage or urge someone to do something",difficulty:2,mnemonic:"'EX-HORT' — like an EX-HORSE trainer who URGES you forward. 'Go! Do it! You can do this!' Strong encouragement.",etymology:"Latin 'exhortari' = to encourage (ex- 'thoroughly' + hortari 'to encourage')",exampleSentence:"The coach exhorted his players to give their maximum effort in the final quarter.",synonyms:["urge","encourage","implore","beseech","admonish"],antonyms:["discourage","dissuade","deter","caution"],confusedWith:["extort"],tags:["encouragement","action"]},
  {word:"exigent",partOfSpeech:"adjective",definition:"pressing; demanding; requiring immediate action or attention",difficulty:3,mnemonic:"'EXIT-GENT' — a GENTLEMAN who needs to EXIT immediately! The situation is so urgent he must leave NOW.",etymology:"Latin 'exigere' = to drive out, demand (ex- 'out' + agere 'to drive')",exampleSentence:"The exigent circumstances required an immediate decision from the board.",synonyms:["urgent","pressing","critical","demanding","imperative"],antonyms:["unimportant","trivial","relaxed","leisurely"],confusedWith:["exiguous"],tags:["urgency","demand"]},
  {word:"extraneous",partOfSpeech:"adjective",definition:"irrelevant or unrelated to the subject being dealt with; of external origin",difficulty:2,mnemonic:"'EXTRA-NEOUS' — EXTRA stuff that doesn't belong. Like EXTRA toppings on a pizza you didn't order — they're extraneous!",etymology:"Latin 'extraneus' = external (from 'extra' = outside)",exampleSentence:"The editor removed all extraneous details that distracted from the main argument.",synonyms:["irrelevant","unrelated","superfluous","immaterial","tangential"],antonyms:["relevant","essential","pertinent","germane"],confusedWith:["extraordinary"],tags:["relevance","unnecessary"]},
  {word:"extravagant",partOfSpeech:"adjective",definition:"lacking restraint in spending money or using resources; exceeding what is reasonable",difficulty:1,mnemonic:"'EXTRA-VAGANT' — EXTRA + VAGRANT (wandering). Spending that WANDERS way beyond what's reasonable!",etymology:"Latin 'extravagans' = wandering outside (extra- 'outside' + vagari 'to wander')",exampleSentence:"The CEO's extravagant spending on personal travel drew criticism from shareholders.",synonyms:["lavish","excessive","profligate","wasteful","exorbitant"],antonyms:["frugal","modest","economical","thrifty"],confusedWith:[],tags:["spending","excess"]},
  {word:"exult",partOfSpeech:"verb",definition:"to show or feel elation or jubilation, especially as the result of a success",difficulty:2,mnemonic:"'EX-ULT' — the ULTimate happiness! Like getting the ULTIMATE result and jumping for joy!",etymology:"Latin 'exsultare' = to leap for joy (ex- 'out' + saltare 'to leap')",exampleSentence:"The team exulted after securing the championship title in the final seconds.",synonyms:["rejoice","celebrate","triumph","delight","revel"],antonyms:["mourn","grieve","lament","despair"],confusedWith:["exalt","insult"],tags:["emotion","joy"]},
  {word:"fabricate",partOfSpeech:"verb",definition:"to invent or concoct something, typically with deceitful intent; to construct or manufacture",difficulty:1,mnemonic:"'FABRIC-ATE' — to weave together a FABRIC of lies. Manufacturing a fake story thread by thread!",etymology:"Latin 'fabricare' = to construct (from 'fabrica' = workshop, from 'faber' = craftsman)",exampleSentence:"The witness was later found to have fabricated his entire testimony.",synonyms:["invent","concoct","falsify","forge","manufacture"],antonyms:["verify","confirm","authenticate"],confusedWith:["fabric"],tags:["deception","creation"]},
  {word:"fallacious",partOfSpeech:"adjective",definition:"based on a mistaken belief; containing a logical error",difficulty:2,mnemonic:"'FALL-ACIOUS' — reasoning that will FALL apart because it's FALLACY-ous. Built on false logic!",etymology:"Latin 'fallaciosus' = deceitful (from 'fallacia' = deception, from 'fallax' = deceptive)",exampleSentence:"The argument was fallacious, relying on a correlation that didn't prove causation.",synonyms:["false","erroneous","misleading","spurious","unsound"],antonyms:["valid","sound","logical","true"],confusedWith:["felicitous"],tags:["logic","false"]},
  {word:"fathom",partOfSpeech:"verb/noun",definition:"to understand after much thought; a unit of length equal to six feet (used for water depth)",difficulty:1,mnemonic:"'FATHOM' — to reach the BOTTOM of understanding, like measuring the DEPTH of water. 'I can't fathom why...' = I can't reach the bottom of this idea.",etymology:"Old English 'fæthm' = embrace, outstretched arms (roughly 6 feet) — extended to mean 'to get to the bottom of'",exampleSentence:"She couldn't fathom why anyone would voluntarily move to such a remote location.",synonyms:["understand","comprehend","grasp","penetrate","discern"],antonyms:["misunderstand","confuse"],confusedWith:["phantom"],tags:["understanding","depth"]},
  {word:"fawn",partOfSpeech:"verb",definition:"to give a servile display of exaggerated flattery or affection to gain favor",difficulty:2,mnemonic:"'FAWN' — like a baby deer (fawn) following you around adoringly. Fawning = excessively flattering to gain favor, like a puppy.",etymology:"Old English 'fægnian' = to rejoice, fawn (related to 'fægen' = glad)",exampleSentence:"The staff fawned over the celebrity guest, competing to fulfill her every request.",synonyms:["grovel","flatter","kowtow","toady","ingratiate"],antonyms:["ignore","disregard","criticize","insult"],confusedWith:[],tags:["behavior","servile"]},
  {word:"feckless",partOfSpeech:"adjective",definition:"lacking initiative or strength of character; irresponsible",difficulty:2,mnemonic:"'FECK-LESS' — LESS EFFECT. A feckless person has LESS effect on anything because they're useless and irresponsible!",etymology:"Scots 'feck' = value, effect (from 'effect') + '-less' — literally 'without effect'",exampleSentence:"The feckless manager failed to address any of the team's concerns.",synonyms:["useless","worthless","incompetent","irresponsible","ineffectual"],antonyms:["competent","responsible","effective","capable"],confusedWith:[],tags:["character","negative"]},
  {word:"felicitous",partOfSpeech:"adjective",definition:"well chosen or suited to the circumstances; pleasing and fortunate",difficulty:3,mnemonic:"'FELICIT-OUS' — like FELICITY (happiness). A felicitous remark is so perfectly suited it brings happiness. The right words at the right time!",etymology:"Latin 'felicitas' = happiness, good fortune (from 'felix' = happy, lucky)",exampleSentence:"The ambassador made a felicitous choice of words that delighted both delegations.",synonyms:["apt","appropriate","fitting","fortunate","well-chosen"],antonyms:["inappropriate","unfortunate","unsuitable","infelicitous"],confusedWith:["fallacious"],tags:["language","fitting"]},
  {word:"fiasco",partOfSpeech:"noun",definition:"a thing that is a complete failure, especially in a ludicrous or humiliating way",difficulty:1,mnemonic:"'FI-ASCO' — 'FI! AS if CO!' (What a failure!) Or: a FLASK (fiasco means flask in Italian) that shatters dramatically. Total disaster!",etymology:"Italian 'fiasco' = bottle, flask — 'far fiasco' = to make a bottle (meaning to fail, possibly from glassblowers' failures)",exampleSentence:"The product launch was a fiasco, with the website crashing within minutes.",synonyms:["disaster","catastrophe","debacle","failure","mess"],antonyms:["success","triumph","achievement"],confusedWith:[],tags:["failure","event"]},
  {word:"fidelity",partOfSpeech:"noun",definition:"faithfulness to a person, cause, or belief; the degree of exactness with which something is copied or reproduced",difficulty:1,mnemonic:"'FIDEL-ITY' — like FIDEL (faithful). Fidelity = being FAITHFUL. High-fidelity audio = faithful reproduction of sound.",etymology:"Latin 'fidelitas' = faithfulness (from 'fidelis' = faithful, from 'fides' = faith)",exampleSentence:"The museum's reproduction was remarkable for its fidelity to the original masterpiece.",synonyms:["loyalty","faithfulness","devotion","allegiance","accuracy"],antonyms:["infidelity","disloyalty","betrayal","treachery"],confusedWith:["infidelity"],tags:["loyalty","accuracy"]},
  {word:"flagrant",partOfSpeech:"adjective",definition:"conspicuously or obviously offensive; blatant and outrageous",difficulty:1,mnemonic:"'FLAG-RANT' — so bad it raises a red FLAG while someone RANTS about it. Impossible to ignore or excuse!",etymology:"Latin 'flagrans' = blazing, burning (from 'flagrare' = to burn) — so bad it's 'on fire' with obviousness",exampleSentence:"The referee called a foul for the player's flagrant violation of the rules.",synonyms:["blatant","glaring","outrageous","egregious","brazen"],antonyms:["subtle","hidden","slight","minor"],confusedWith:["fragrant"],tags:["obvious","negative"]},
  {word:"fleeting",partOfSpeech:"adjective",definition:"lasting for a very short time; passing quickly",difficulty:1,mnemonic:"'FLEET-ING' — like a FLEET of ships passing by quickly on the horizon. Here one moment, gone the next.",etymology:"Old English 'fleotan' = to float, swim (related to 'fleet' = swift)",exampleSentence:"She caught only a fleeting glimpse of the suspect before he disappeared into the crowd.",synonyms:["brief","momentary","transient","ephemeral","short-lived"],antonyms:["lasting","enduring","permanent","eternal"],confusedWith:["floating"],tags:["time","brief"]},
  {word:"foment",partOfSpeech:"verb",definition:"to instigate or stir up an undesirable or violent sentiment or action",difficulty:2,mnemonic:"'FOAM-ENT' — stirring up FOAM like a witch stirring a cauldron. Fomenting trouble = stirring up chaos!",etymology:"Latin 'fomentare' = to apply a warm poultice (from 'fovere' = to warm, cherish) — evolved to mean 'to incite'",exampleSentence:"The opposition leader was accused of fomenting unrest among the workers.",synonyms:["instigate","incite","provoke","stir up","agitate"],antonyms:["quell","suppress","calm","pacify"],confusedWith:["ferment"],tags:["incitement","action"]},
  {word:"forthright",partOfSpeech:"adjective",definition:"direct and outspoken; straightforward and honest",difficulty:1,mnemonic:"'FORTH-RIGHT' — going FORTH (forward) on the RIGHT path. Straight ahead, no detours, no lies.",etymology:"Old English 'forthriht' = straight ahead (forth + right)",exampleSentence:"Her forthright assessment of the situation, while uncomfortable, was exactly what the team needed.",synonyms:["direct","candid","frank","honest","straightforward"],antonyms:["evasive","indirect","deceptive","dishonest"],confusedWith:[],tags:["honesty","communication"]},
  {word:"foster",partOfSpeech:"verb",definition:"to encourage or promote the development of something; to bring up a child not one's own",difficulty:1,mnemonic:"'FOSTER' — like a FOSTER parent who nurtures and encourages growth. To foster an idea = to nurture it.",etymology:"Old English 'fostrian' = to nourish, rear (from 'fostor' = food, nourishment)",exampleSentence:"The program was designed to foster creativity and innovation among students.",synonyms:["encourage","promote","nurture","cultivate","support"],antonyms:["hinder","discourage","suppress","neglect"],confusedWith:[],tags:["growth","support"]},
  {word:"fractious",partOfSpeech:"adjective",definition:"easily irritated; quarrelsome and unruly; difficult to control",difficulty:2,mnemonic:"'FRACT-IOUS' — like a FRACTION that breaks apart. A fractious group is broken into arguing FRACTIONS, always fighting!",etymology:"From 'fraction' (breaking) + '-ious' — literally 'tending to break apart'",exampleSentence:"The fractious committee couldn't agree on even the most basic procedural matters.",synonyms:["irritable","quarrelsome","unruly","contentious","peevish"],antonyms:["agreeable","cooperative","docile","compliant"],confusedWith:["factious","fractured"],tags:["behavior","difficult"]},
  {word:"futile",partOfSpeech:"adjective",definition:"incapable of producing any useful result; pointless",difficulty:1,mnemonic:"'FEW-TILE' — like FEW TILES left to fix a whole roof. Completely inadequate and pointless to even try.",etymology:"Latin 'futilis' = leaky, unreliable (from 'fundere' = to pour) — like a leaky vessel that can't hold anything useful",exampleSentence:"Their efforts to negotiate a compromise proved futile as neither side would budge.",synonyms:["pointless","useless","vain","fruitless","unavailing"],antonyms:["productive","useful","effective","fruitful"],confusedWith:["fertile"],tags:["result","negative"]},
  {word:"galvanize",partOfSpeech:"verb",definition:"to shock or excite someone into taking action; to coat with zinc",difficulty:2,mnemonic:"'GALVANI-ZE' — named after Luigi GALVANI who made dead frog legs twitch with electricity. To galvanize = to SHOCK into action!",etymology:"From Luigi Galvani (1737-1798), Italian scientist who discovered electrical stimulation of muscles",exampleSentence:"The crisis galvanized the community into organizing a massive relief effort.",synonyms:["stimulate","motivate","inspire","spur","electrify"],antonyms:["discourage","demotivate","bore","dampen"],confusedWith:[],tags:["action","motivation"]},
  {word:"germane",partOfSpeech:"adjective",definition:"relevant to a subject under consideration; fitting and appropriate",difficulty:2,mnemonic:"'GERMAN-E' — think of GERMAN efficiency — everything must be relevant and on-topic. No wasted words! If it's germane, it belongs.",etymology:"Variant of 'german' = closely related (Latin 'germanus' = genuine, of the same parents)",exampleSentence:"The lawyer objected, arguing that the question was not germane to the case.",synonyms:["relevant","pertinent","applicable","apropos","related"],antonyms:["irrelevant","unrelated","extraneous","immaterial"],confusedWith:["German"],tags:["relevance","discussion"]},
  {word:"glacial",partOfSpeech:"adjective",definition:"extremely slow; extremely cold or icy; unfriendly",difficulty:1,mnemonic:"'GLACIER-AL' — like a GLACIER: extremely slow-moving and ice cold. A glacial pace = painfully slow. A glacial stare = icy cold.",etymology:"Latin 'glacialis' = icy (from 'glacies' = ice)",exampleSentence:"Progress on the reforms has been glacial, frustrating advocates who expected swift action.",synonyms:["slow","frigid","icy","hostile","frozen"],antonyms:["fast","warm","friendly","rapid"],confusedWith:[],tags:["speed","temperature"]},
  {word:"glib",partOfSpeech:"adjective",definition:"fluent and voluble but insincere and shallow; smooth-talking",difficulty:2,mnemonic:"'GLIB' — like a SLIPPERY LIP. Words slide out too smoothly, too easily — probably not sincere. Suspiciously smooth!",etymology:"Possibly from Low German 'glibberig' = slippery",exampleSentence:"The salesman's glib assurances about the product's quality raised suspicion.",synonyms:["slick","smooth","superficial","facile","insincere"],antonyms:["sincere","thoughtful","inarticulate","genuine"],confusedWith:["flip"],tags:["speech","insincere"]},
  {word:"gratuitous",partOfSpeech:"adjective",definition:"uncalled for; lacking good reason; given or done free of charge",difficulty:2,mnemonic:"'GRATU-IT-OUS' — GRATUITY (tip) is free. But gratuitous violence = unnecessary, uncalled for. Free but unwanted!",etymology:"Latin 'gratuitus' = free, freely given (from 'gratus' = pleasing, grateful)",exampleSentence:"The film was criticized for its gratuitous violence that added nothing to the plot.",synonyms:["unnecessary","unwarranted","unjustified","uncalled-for","needless"],antonyms:["necessary","warranted","justified","essential"],confusedWith:["grateful","gratuity"],tags:["unnecessary","free"]},
  {word:"guile",partOfSpeech:"noun",definition:"sly or cunning intelligence; craftiness",difficulty:2,mnemonic:"'GUILE' — like a sly SMILE (guile/smile rhyme-ish). Behind that innocent smile is cunning deception and trickery.",etymology:"Old French 'guile' = deceit, trickery (from Frankish *wigila = trick)",exampleSentence:"Through guile rather than force, the spy obtained the classified documents.",synonyms:["cunning","craftiness","deception","duplicity","artfulness"],antonyms:["honesty","candor","sincerity","guilelessness"],confusedWith:["guilt"],tags:["deception","intelligence"]},
  {word:"hapless",partOfSpeech:"adjective",definition:"unfortunate; having no luck",difficulty:2,mnemonic:"'HAP-LESS' — LESS HAPPINESS, LESS luck. HAP = luck (like 'happenstance'). Hapless = without luck. Poor thing!",etymology:"From 'hap' (luck, fortune) + '-less' — literally 'without luck'",exampleSentence:"The hapless tourist was scammed three times on his first day in the city.",synonyms:["unlucky","unfortunate","luckless","wretched","ill-fated"],antonyms:["lucky","fortunate","blessed","charmed"],confusedWith:["helpless"],tags:["luck","negative"]},
  {word:"hardy",partOfSpeech:"adjective",definition:"robust; capable of enduring difficult conditions; bold and daring",difficulty:1,mnemonic:"'HARD-Y' — HARD + Y. Someone who's hard as nails, tough enough to survive anything!",etymology:"Old French 'hardi' = bold, daring (from Frankish *hardjan = to make hard)",exampleSentence:"Only the hardiest plants can survive the harsh conditions of the alpine tundra.",synonyms:["robust","resilient","tough","durable","sturdy"],antonyms:["fragile","delicate","weak","tender"],confusedWith:["hearty"],tags:["strength","endurance"]},
  {word:"haughty",partOfSpeech:"adjective",definition:"arrogantly superior and disdainful; looking down on others",difficulty:1,mnemonic:"'HAUGHT-Y' — standing at a great HEIGHT looking down on everyone. Too HIGH and mighty for the common people!",etymology:"Middle English 'haute' = high, lofty (from French 'haut' = high, from Latin 'altus')",exampleSentence:"Her haughty manner alienated potential allies who might otherwise have supported her cause.",synonyms:["arrogant","proud","supercilious","condescending","snobbish"],antonyms:["humble","modest","meek","unassuming"],confusedWith:["naughty"],tags:["attitude","arrogance"]},
  {word:"hedonist",partOfSpeech:"noun",definition:"a person who believes that the pursuit of pleasure is the most important thing in life",difficulty:2,mnemonic:"'HE-DON-IST' — 'HE's DONE with responsibility, now it's all about pleasure!' A hedonist only cares about enjoyment.",etymology:"Greek 'hedone' = pleasure",exampleSentence:"The emperor was a notorious hedonist who spent lavishly on banquets and entertainment.",synonyms:["pleasure-seeker","sensualist","sybarite","epicurean"],antonyms:["ascetic","puritan","stoic","abstainer"],confusedWith:[],tags:["lifestyle","pleasure"]},
  {word:"heresy",partOfSpeech:"noun",definition:"belief or opinion contrary to orthodox religious or accepted doctrine; a controversial opinion",difficulty:2,mnemonic:"'HERE-SY' — 'HERE, SEE? This belief is WRONG!' That's how the church would react to heresy — pointing it out as forbidden thinking.",etymology:"Greek 'hairesis' = choice, school of thought (from 'hairein' = to take, choose)",exampleSentence:"In the academic world, questioning the established theory was treated as heresy.",synonyms:["dissent","blasphemy","unorthodoxy","heterodoxy","apostasy"],antonyms:["orthodoxy","conformity","dogma"],confusedWith:["hearsay"],tags:["belief","opposition"]},
  {word:"hierarchy",partOfSpeech:"noun",definition:"a system in which members are ranked according to relative status or authority",difficulty:1,mnemonic:"'HIER-ARCHY' — HIGHER-ARCHY. A system where some are HIGHER than others. Ranked from top to bottom.",etymology:"Greek 'hierarkhia' = rule of a high priest (hieros 'sacred' + arkhein 'to rule')",exampleSentence:"The rigid hierarchy of the organization prevented junior employees from sharing innovative ideas.",synonyms:["ranking","order","pecking order","chain of command","stratification"],antonyms:["equality","egalitarianism"],confusedWith:[],tags:["structure","power"]},
  {word:"hubris",partOfSpeech:"noun",definition:"excessive pride or self-confidence; arrogance that often leads to downfall",difficulty:2,mnemonic:"'HUB-RIS' — imagine a HUB (center) that thinks it's the center of the universe. That's HUBRIS — deadly pride that risks everything!",etymology:"Greek 'hybris' = insolence, wanton violence (originally meant an insult to the gods through excessive pride)",exampleSentence:"The CEO's hubris in ignoring market warnings led to the company's spectacular collapse.",synonyms:["arrogance","conceit","pride","presumption","overconfidence"],antonyms:["humility","modesty","meekness"],confusedWith:[],tags:["pride","downfall"]},
  {word:"hyperbole",partOfSpeech:"noun",definition:"exaggerated statements or claims not meant to be taken literally",difficulty:1,mnemonic:"'HYPER-BOLE' — HYPER = excessive. HYPER + BOWL = an excessively large bowl! 'I'm so hungry I could eat a horse' — that's hyperbole!",etymology:"Greek 'hyperbole' = excess (hyper- 'beyond' + bole 'a throwing')",exampleSentence:"Saying the bag weighed a ton was pure hyperbole; it was only about ten pounds.",synonyms:["exaggeration","overstatement","magnification","embellishment"],antonyms:["understatement","litotes","meiosis"],confusedWith:[],tags:["language","rhetoric"]},
  {word:"iconoclastic",partOfSpeech:"adjective",definition:"criticizing or attacking cherished beliefs or institutions; breaking with tradition",difficulty:2,mnemonic:"'ICON-O-CLASTIC' — CLASTING (smashing) ICONS. Breaking the sacred images and established beliefs. Revolutionary!",etymology:"Greek 'eikonoklastes' = image breaker (eikon 'image' + klan 'to break')",exampleSentence:"The filmmaker's iconoclastic approach challenged every convention of the genre.",synonyms:["revolutionary","nonconformist","rebellious","subversive","radical"],antonyms:["conventional","traditional","orthodox","conformist"],confusedWith:["iconoclast"],tags:["rebellion","tradition"]},
  {word:"idiosyncrasy",partOfSpeech:"noun",definition:"a mode of behavior or way of thought peculiar to an individual; a distinctive characteristic",difficulty:2,mnemonic:"'IDIO-SYNC-RASY' — your own IDIO(personal) SYNC(rhythm). Your unique quirk that doesn't sync with anyone else's!",etymology:"Greek 'idiosunkrasia' = personal temperament (idios 'own, private' + sun 'with' + krasis 'mixture')",exampleSentence:"One of her endearing idiosyncrasies was always wearing mismatched socks.",synonyms:["quirk","peculiarity","eccentricity","foible","mannerism"],antonyms:["norm","convention","standard"],confusedWith:["idiot"],tags:["personality","unique"]},
  {word:"impasse",partOfSpeech:"noun",definition:"a situation in which no progress is possible; a deadlock",difficulty:1,mnemonic:"'IM-PASS' — you can NOT PASS! Like a wall blocking a road. An impasse = a dead end where no one can move forward.",etymology:"French 'impasse' = dead end (im- 'not' + passer 'to pass')",exampleSentence:"Negotiations reached an impasse when neither side would compromise on the key issues.",synonyms:["deadlock","stalemate","standstill","gridlock","dead end"],antonyms:["breakthrough","progress","resolution","agreement"],confusedWith:["impassive"],tags:["conflict","stuck"]},
  {word:"impede",partOfSpeech:"verb",definition:"to delay or prevent by obstructing; to hinder",difficulty:1,mnemonic:"'IM-PEDE' — shackles on your PEDES (feet, like pedestrian). Can't walk! Something blocking your feet from moving forward.",etymology:"Latin 'impedire' = to shackle the feet (in- 'in' + pes/pedis 'foot')",exampleSentence:"Bureaucratic red tape continued to impede progress on the infrastructure project.",synonyms:["hinder","obstruct","hamper","block","delay"],antonyms:["facilitate","assist","advance","expedite"],confusedWith:["impale"],tags:["obstruction","prevention"]},
  {word:"imperative",partOfSpeech:"adjective/noun",definition:"of vital importance; crucial; giving an authoritative command",difficulty:1,mnemonic:"'EMPEROR-ATIVE' — when an EMPEROR commands, it's IMPERATIVE — you MUST obey! Absolutely essential!",etymology:"Latin 'imperativus' = commanding (from 'imperare' = to command; in- + parare 'to prepare')",exampleSentence:"It is imperative that we address the security vulnerabilities before the product launch.",synonyms:["essential","crucial","vital","urgent","mandatory"],antonyms:["optional","unnecessary","unimportant","trivial"],confusedWith:["imperial"],tags:["importance","command"]},
  {word:"imperious",partOfSpeech:"adjective",definition:"assuming power or authority without justification; domineering",difficulty:2,mnemonic:"'EMPEROR-IOUS' — acting like an EMPEROR without being one. Bossy and commanding, like a dictator in the office.",etymology:"Latin 'imperiosus' = commanding (from 'imperium' = command, power)",exampleSentence:"Her imperious tone made it clear she expected compliance, not discussion.",synonyms:["domineering","authoritarian","overbearing","dictatorial","bossy"],antonyms:["humble","submissive","meek","deferential"],confusedWith:["impervious","imperial"],tags:["authority","arrogance"]},
  {word:"impertinent",partOfSpeech:"adjective",definition:"not showing proper respect; rude; not pertinent or relevant",difficulty:1,mnemonic:"'IM-PERTINENT' — IM (not) + PERTINENT (relevant). Originally meant irrelevant, now mainly means RUDE. Either way: out of line!",etymology:"Latin 'impertinens' = not pertaining (in- 'not' + pertinere 'to pertain')",exampleSentence:"The student's impertinent question was clearly intended to provoke the teacher.",synonyms:["rude","insolent","disrespectful","impudent","irrelevant"],antonyms:["polite","respectful","pertinent","relevant"],confusedWith:["impotent","important"],tags:["behavior","rude"]},
  {word:"impetus",partOfSpeech:"noun",definition:"the force or energy with which a body moves; a driving force behind something",difficulty:2,mnemonic:"'IM-PET-US' — like an impatient PET rushing at US with force. The driving energy that pushes things forward!",etymology:"Latin 'impetus' = attack, force (from 'impetere' = to rush at; in- 'toward' + petere 'to seek, rush at')",exampleSentence:"The scandal provided the impetus for long-overdue reforms in campaign finance.",synonyms:["motivation","stimulus","incentive","momentum","catalyst"],antonyms:["hindrance","deterrent","obstacle","brake"],confusedWith:["impetuous"],tags:["force","motivation"]},
  {word:"implicate",partOfSpeech:"verb",definition:"to show someone to be involved in a crime; to convey a meaning indirectly",difficulty:1,mnemonic:"'IM-PLICATE' — to fold someone IN (implicate = fold in, like complicate). Folding them into the crime!",etymology:"Latin 'implicare' = to entangle (in- 'in' + plicare 'to fold')",exampleSentence:"The evidence implicated several senior officials in the corruption scheme.",synonyms:["involve","incriminate","connect","entangle","insinuate"],antonyms:["exonerate","absolve","exclude","clear"],confusedWith:["complicate","imply"],tags:["crime","involvement"]},
  {word:"implicit",partOfSpeech:"adjective",definition:"implied though not plainly expressed; unquestioning; absolute",difficulty:1,mnemonic:"'IM-PLICIT' — folded INSIDE, not visible on the surface. The meaning is there but you have to unfold it. Opposite of explicit!",etymology:"Latin 'implicitus' = entangled, involved (from 'implicare' = to enfold)",exampleSentence:"There was an implicit understanding that the information would remain confidential.",synonyms:["implied","unspoken","understood","inherent","tacit"],antonyms:["explicit","stated","expressed","overt"],confusedWith:["explicit","complicit"],tags:["meaning","hidden"]},
  {word:"impugn",partOfSpeech:"verb",definition:"to dispute the truth, validity, or honesty of; to call into question",difficulty:3,mnemonic:"'IM-PUGN' — to PUNCH (pugn, like pugnacious) someone's argument. Fighting against their credibility!",etymology:"Latin 'impugnare' = to attack (in- 'toward' + pugnare 'to fight')",exampleSentence:"The attorney attempted to impugn the credibility of the prosecution's key witness.",synonyms:["challenge","question","dispute","attack","contest"],antonyms:["support","defend","endorse","uphold"],confusedWith:["impugn"],tags:["challenge","credibility"]},
  {word:"inadvertent",partOfSpeech:"adjective",definition:"not resulting from or achieved through deliberate planning; unintentional",difficulty:1,mnemonic:"'IN-ADVERT-ENT' — IN (not) + ADVERT (pay attention). Not paying attention = accidental. An inadvertent mistake.",etymology:"Latin 'inadvertere' = not turn the mind to (in- 'not' + advertere 'to turn toward')",exampleSentence:"The inadvertent disclosure of confidential data led to a major security investigation.",synonyms:["unintentional","accidental","unplanned","unwitting"],antonyms:["deliberate","intentional","planned","purposeful"],confusedWith:["inadvisable"],tags:["intention","accidental"]},
  {word:"incisive",partOfSpeech:"adjective",definition:"intelligently analytical and clear-thinking; sharp and direct",difficulty:2,mnemonic:"'IN-CISE-IVE' — like an INCISION from a surgeon's knife. Cutting right to the heart of the matter with sharp precision!",etymology:"Latin 'incisivus' = cutting into (from 'incidere' = to cut into; in- + caedere 'to cut')",exampleSentence:"Her incisive analysis of the market trends impressed the entire investment committee.",synonyms:["sharp","keen","penetrating","astute","perceptive"],antonyms:["dull","vague","superficial","muddled"],confusedWith:["decisive"],tags:["intelligence","sharp"]},
  {word:"incongruous",partOfSpeech:"adjective",definition:"not in harmony or keeping with the surroundings; inappropriate",difficulty:2,mnemonic:"'IN-CONGRUENT-OUS' — NOT CONGRUENT (matching). Like wearing a swimsuit to a job interview — totally out of place!",etymology:"Latin 'incongruus' = not agreeing (in- 'not' + congruus 'agreeing, suitable')",exampleSentence:"The modern glass building looked incongruous amid the historic stone architecture.",synonyms:["incompatible","inappropriate","discordant","out of place","absurd"],antonyms:["congruent","fitting","appropriate","harmonious"],confusedWith:["inconsequential"],tags:["mismatch","inappropriate"]},
  {word:"indifferent",partOfSpeech:"adjective",definition:"having no particular interest or sympathy; unconcerned; mediocre",difficulty:1,mnemonic:"'IN-DIFFERENT' — unable to tell the DIFFERENCE because you don't care. Nothing matters — total apathy.",etymology:"Latin 'indifferens' = not differing (in- 'not' + differens 'differing')",exampleSentence:"The committee seemed indifferent to the concerns raised by the local residents.",synonyms:["apathetic","unconcerned","uninterested","detached","blasé"],antonyms:["concerned","interested","passionate","enthusiastic"],confusedWith:["different"],tags:["emotion","apathy"]},
  {word:"indignant",partOfSpeech:"adjective",definition:"feeling or showing anger or annoyance at what is perceived as unfair treatment",difficulty:1,mnemonic:"'IN-DIG-NANT' — your DIGNITY has been insulted! You're angry because something unfair happened. Righteous anger!",etymology:"Latin 'indignari' = to regard as unworthy (in- 'not' + dignus 'worthy')",exampleSentence:"The employees were indignant when they learned about the executive bonus scandal.",synonyms:["outraged","angry","offended","incensed","irate"],antonyms:["pleased","content","calm","delighted"],confusedWith:["indigenous"],tags:["emotion","anger"]},
  {word:"indolent",partOfSpeech:"adjective",definition:"wanting to avoid activity or exertion; lazy",difficulty:2,mnemonic:"'IN-DOLENT' — sounds like 'IN the DOLL-ENT' — lying around like a rag doll, too lazy to move.",etymology:"Latin 'indolens' = without pain (in- 'not' + dolere 'to suffer, give pain') — if you feel no pain/urgency, why bother moving?",exampleSentence:"The indolent student waited until the last minute to start his research paper.",synonyms:["lazy","idle","sluggish","slothful","lethargic"],antonyms:["industrious","energetic","diligent","active"],confusedWith:["insolent"],tags:["behavior","lazy"]},
  {word:"indulgent",partOfSpeech:"adjective",definition:"having or indicating a tendency to be overly generous or lenient with someone",difficulty:1,mnemonic:"'IN-DULGE-NT' — someone who INDULGES others, giving them whatever they want. Spoiling them!",etymology:"Latin 'indulgens' = kind, tender (from 'indulgere' = to grant as a favor)",exampleSentence:"The indulgent grandmother could never say no to her grandchildren's requests.",synonyms:["lenient","permissive","tolerant","liberal","pampering"],antonyms:["strict","stern","harsh","austere"],confusedWith:["indolent"],tags:["behavior","lenient"]},
  {word:"inert",partOfSpeech:"adjective",definition:"lacking the ability or strength to move; lacking the power to act",difficulty:1,mnemonic:"'IN-ERT' — NOT EXERTING any energy. Just sitting there doing nothing. Like a noble gas that won't react with anything.",etymology:"Latin 'iners' = unskilled, inactive (in- 'not' + ars 'skill, art')",exampleSentence:"The government appeared inert in the face of the growing humanitarian crisis.",synonyms:["inactive","motionless","static","dormant","passive"],antonyms:["active","dynamic","energetic","reactive"],confusedWith:["inept"],tags:["inactivity","state"]},
  {word:"inexorable",partOfSpeech:"adjective",definition:"impossible to stop or prevent; impossible to persuade by request or entreaty",difficulty:3,mnemonic:"'IN-EXOR-ABLE' — NOT able to be EXORCISED (driven away). Like a demon you can't get rid of — relentless, unstoppable!",etymology:"Latin 'inexorabilis' = relentless (in- 'not' + exorabilis 'able to be moved by entreaty', from 'exorare' = to prevail upon)",exampleSentence:"The inexorable rise of sea levels threatens coastal communities worldwide.",synonyms:["relentless","unstoppable","inevitable","unrelenting","implacable"],antonyms:["stoppable","preventable","flexible","yielding"],confusedWith:["inextricable"],tags:["unstoppable","inevitable"]},
  {word:"innocuous",partOfSpeech:"adjective",definition:"not harmful or offensive; harmless",difficulty:2,mnemonic:"'IN-NOCK-UOUS' — it won't KNOCK you out. Harmless, gentle, posing no threat whatsoever.",etymology:"Latin 'innocuus' = harmless (in- 'not' + nocuus 'harmful', from 'nocere' = to harm)",exampleSentence:"What seemed like an innocuous comment sparked a heated debate among the panelists.",synonyms:["harmless","inoffensive","benign","safe","mild"],antonyms:["harmful","dangerous","offensive","noxious"],confusedWith:["innocent","inoculate"],tags:["safety","harmless"]},
  {word:"inscrutable",partOfSpeech:"adjective",definition:"impossible to understand or interpret; mysterious",difficulty:2,mnemonic:"'IN-SCRUTABLE' — you can't SCRUTINIZE it because it's too mysterious. Can't inspect or understand it no matter how hard you look.",etymology:"Latin 'inscrutabilis' = unsearchable (in- 'not' + scrutari 'to examine, search')",exampleSentence:"The diplomat maintained an inscrutable expression throughout the tense negotiations.",synonyms:["enigmatic","mysterious","unfathomable","impenetrable","cryptic"],antonyms:["transparent","clear","obvious","readable"],confusedWith:["insatiable"],tags:["mystery","understanding"]},
  {word:"insidious",partOfSpeech:"adjective",definition:"proceeding in a gradual, subtle way, but with harmful effects",difficulty:2,mnemonic:"'IN-SIDIOUS' — the danger is on the INSIDE, hidden. It creeps in slowly like a snake. You don't notice until it's too late.",etymology:"Latin 'insidiosus' = cunning, deceitful (from 'insidiae' = ambush; in- 'in' + sedere 'to sit' — literally 'sitting in wait')",exampleSentence:"The insidious effects of prolonged stress often go unnoticed until they cause serious health problems.",synonyms:["stealthy","subtle","treacherous","sly","gradual"],antonyms:["obvious","forthright","harmless","overt"],confusedWith:["insipid"],tags:["harm","subtle"]},
  {word:"insolent",partOfSpeech:"adjective",definition:"showing a rude and arrogant lack of respect",difficulty:1,mnemonic:"'IN-SOLE-ENT' — like someone who puts their dirty SOLE (shoe bottom) on your desk. Disrespectful and rude!",etymology:"Latin 'insolens' = unusual, arrogant (in- 'not' + solens 'being accustomed') — unaccustomed to proper behavior",exampleSentence:"The insolent teenager rolled his eyes when his teacher asked him to pay attention.",synonyms:["rude","disrespectful","impudent","impertinent","brazen"],antonyms:["polite","respectful","deferential","courteous"],confusedWith:["indolent","insolvent"],tags:["behavior","rude"]},
  {word:"integrity",partOfSpeech:"noun",definition:"the quality of being honest and having strong moral principles; the state of being whole and undivided",difficulty:1,mnemonic:"'INTEGER-ITY' — like an INTEGER (whole number), someone with integrity is WHOLE and undivided in their morals. Complete and unbroken.",etymology:"Latin 'integritas' = wholeness, soundness (from 'integer' = intact, whole; in- 'not' + tangere 'to touch')",exampleSentence:"Her integrity made her the obvious choice to lead the ethics investigation.",synonyms:["honesty","honor","virtue","uprightness","wholeness"],antonyms:["dishonesty","corruption","deceit"],confusedWith:["integrate"],tags:["character","virtue"]},
  {word:"intrepid",partOfSpeech:"adjective",definition:"fearless; adventurous; extremely bold and brave",difficulty:2,mnemonic:"'IN-TREPID' — IN = not, TREPID = fearful (trepidation). Someone who is NOT afraid. Fearless!",etymology:"Latin 'intrepidus' = unshaken (in- 'not' + trepidus 'alarmed')",exampleSentence:"The intrepid explorer ventured into uncharted territories despite numerous warnings.",synonyms:["fearless","brave","courageous","bold","valiant"],antonyms:["timid","cowardly","fearful","craven"],confusedWith:["insipid"],tags:["courage","positive"]},
  {word:"inundate",partOfSpeech:"verb",definition:"to overwhelm with things to be dealt with; to flood",difficulty:2,mnemonic:"'IN-UNDATE' — imagine water coming IN to UN-DATE (ruin) all your documents! Flooded and overwhelmed!",etymology:"Latin 'inundare' = to overflow (in- 'into' + undare 'to flow', from 'unda' = wave)",exampleSentence:"After the announcement, customer service was inundated with calls and emails.",synonyms:["overwhelm","flood","swamp","deluge","overrun"],antonyms:["drain","dry up","underwhelm"],confusedWith:["invalidate"],tags:["excess","overwhelm"]},
  {word:"invective",partOfSpeech:"noun",definition:"insulting, abusive, or highly critical language",difficulty:2,mnemonic:"'IN-VECT-IVE' — words that INJECT (vect) VENOM into you. Poisonous, abusive language hurled like arrows!",etymology:"Latin 'invectivus' = attacking (from 'invehere' = to carry in, attack; in- + vehere 'to carry')",exampleSentence:"The debate devolved into a series of personal invective rather than policy discussion.",synonyms:["abuse","vitriol","tirade","diatribe","insults"],antonyms:["praise","compliment","flattery","commendation"],confusedWith:["inventive"],tags:["speech","abuse"]},
  {word:"irascible",partOfSpeech:"adjective",definition:"having or showing a tendency to be easily angered; hot-tempered",difficulty:2,mnemonic:"'IRATE-IBLE' — easily becoming IRATE. An irascible person goes from calm to furious in seconds!",etymology:"Latin 'irascibilis' = quick-tempered (from 'irasci' = to be angry, from 'ira' = anger)",exampleSentence:"The irascible professor was known for losing his temper over the smallest disruptions.",synonyms:["irritable","hot-tempered","cantankerous","choleric","tetchy"],antonyms:["calm","easygoing","placid","patient"],confusedWith:["irate"],tags:["personality","anger"]},
  {word:"itinerant",partOfSpeech:"adjective",definition:"traveling from place to place; wandering",difficulty:2,mnemonic:"'ITINER-ANT' — from ITINERARY (travel plan). An itinerant worker follows an itinerary from job to job, place to place.",etymology:"Latin 'itinerans' = traveling (from 'iter' = journey, way)",exampleSentence:"The itinerant musician performed in a different city every night.",synonyms:["traveling","wandering","nomadic","roving","peripatetic"],antonyms:["settled","stationary","sedentary","fixed"],confusedWith:["itinerary"],tags:["travel","movement"]}
];
